/**
 * Shared large reading modal for Product + Orbit.
 * API: openReaderModal({ title, kicker?, sections?, html?, showToc? })
 *      closeReaderModal()
 *      sectionsFromDetail(detail, extras?)
 */
(() => {
  let lastFocus = null;
  let onKeyDown = null;

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function getEls() {
    const root = document.getElementById("reader-modal");
    if (!root) return null;
    return {
      root,
      title: document.getElementById("reader-modal-title"),
      kicker: document.getElementById("reader-modal-kicker"),
      toc: document.getElementById("reader-modal-toc"),
      tocList: document.getElementById("reader-modal-toc-list"),
      layout: document.getElementById("reader-modal-layout"),
      body: document.getElementById("reader-modal-body"),
      closeBtn: document.getElementById("reader-modal-close"),
    };
  }

  function renderSections(sections) {
    return (sections || [])
      .map((sec) => {
        const id = sec.id ? ` id="${escapeHtml(sec.id)}"` : "";
        const title = sec.title ? `<h3${id}>${escapeHtml(sec.title)}</h3>` : "";
        const paras = (sec.paragraphs || [])
          .map((p) => `<p>${escapeHtml(p)}</p>`)
          .join("");
        let list = "";
        if (sec.bullets?.length) {
          list = `<ul>${sec.bullets.map((b) => `<li>${escapeHtml(b)}</li>`).join("")}</ul>`;
        } else if (sec.steps?.length) {
          list = `<ol>${sec.steps.map((b) => `<li>${escapeHtml(b)}</li>`).join("")}</ol>`;
        }
        const table = sec.tableHtml || "";
        const html = sec.html || "";
        return `${title}${paras}${list}${table}${html}`;
      })
      .join("");
  }

  function focusable(root) {
    return [
      ...root.querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])',
      ),
    ].filter((el) => !el.hasAttribute("disabled") && el.offsetParent !== null);
  }

  function closeReaderModal() {
    const els = getEls();
    if (!els || els.root.hidden) return;
    els.root.hidden = true;
    document.body.classList.remove("reader-modal-open");
    if (onKeyDown) {
      document.removeEventListener("keydown", onKeyDown);
      onKeyDown = null;
    }
    if (lastFocus && typeof lastFocus.focus === "function") {
      lastFocus.focus();
    }
    lastFocus = null;
  }

  /**
   * @param {{ title: string, kicker?: string, sections?: Array, html?: string, showToc?: boolean }} opts
   */
  function openReaderModal(opts) {
    const els = getEls();
    if (!els) return;

    lastFocus = document.activeElement;
    const title = opts.title || "Details";
    const kicker = opts.kicker || "Reading view";
    const sections = opts.sections || [];
    const showToc = Boolean(opts.showToc && sections.length);

    els.title.textContent = title;
    els.kicker.textContent = kicker;
    els.layout.classList.toggle("has-toc", showToc);
    els.toc.hidden = !showToc;

    if (showToc) {
      els.tocList.innerHTML = sections
        .filter((s) => s.id && s.title)
        .map(
          (s) =>
            `<a href="#${escapeHtml(s.id)}">${escapeHtml(s.title)}</a>`,
        )
        .join("");
      els.tocList.querySelectorAll("a").forEach((a) => {
        a.addEventListener("click", (e) => {
          e.preventDefault();
          const id = a.getAttribute("href")?.slice(1);
          const target = id ? els.body.querySelector(`#${CSS.escape(id)}`) : null;
          if (target) target.scrollIntoView({ behavior: "smooth", block: "start" });
        });
      });
    } else {
      els.tocList.innerHTML = "";
    }

    els.body.innerHTML = opts.html || renderSections(sections);
    els.body.scrollTop = 0;

    els.root.hidden = false;
    document.body.classList.add("reader-modal-open");
    els.closeBtn.focus();

    onKeyDown = (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        closeReaderModal();
        return;
      }
      if (e.key !== "Tab") return;
      const nodes = focusable(els.root);
      if (!nodes.length) return;
      const first = nodes[0];
      const last = nodes[nodes.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    };
    document.addEventListener("keydown", onKeyDown);
  }

  /** Build modal sections from an orbit/module detail object. */
  function sectionsFromDetail(detail, extras = {}) {
    const sections = [];
    if (detail?.purpose) {
      sections.push({
        id: "purpose",
        title: "Purpose",
        paragraphs: [detail.purpose],
      });
    }
    if (detail?.howItWorks?.length) {
      sections.push({
        id: "how",
        title: "How it works",
        steps: detail.howItWorks,
      });
    }
    if (detail?.acceptance?.length) {
      sections.push({
        id: "acceptance",
        title: "Acceptance / exit signals",
        bullets: detail.acceptance,
      });
    }
    if (detail?.notes?.length) {
      sections.push({
        id: "notes",
        title: "Notes",
        bullets: detail.notes,
      });
    }
    if (detail?.prdRefs || extras.prdRefs) {
      sections.push({
        id: "prd",
        title: "PRD anchors",
        paragraphs: [detail?.prdRefs || extras.prdRefs],
      });
    }
    if (extras.exit) {
      sections.push({
        id: "exit",
        title: "Stint exit criteria",
        paragraphs: [extras.exit],
      });
    }
    return sections;
  }

  function wireModal() {
    const els = getEls();
    if (!els) return;
    els.closeBtn.addEventListener("click", closeReaderModal);
    els.root.addEventListener("click", (e) => {
      if (e.target === els.root) closeReaderModal();
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", wireModal);
  } else {
    wireModal();
  }

  window.openReaderModal = openReaderModal;
  window.closeReaderModal = closeReaderModal;
  window.sectionsFromDetail = sectionsFromDetail;
  window.escapeReaderHtml = escapeHtml;
})();

import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";
import { CSS2DRenderer, CSS2DObject } from "three/addons/renderers/CSS2DRenderer.js";
import { RoomEnvironment } from "three/addons/environments/RoomEnvironment.js";
import { ROADMAP } from "./roadmap-data.js";

const COLORS = {
  paper: 0x0b0e16,
  forest: 0x5fb8a6,
  accent: 0xe3c284,
  client: 0x7fa8d9,
  platform: 0xa390cf,
  line: 0x2c364f,
  ring: 0x4a5578,
  ink: 0xe9edf6,
  star: 0xcdd8f0,
  gymSoft: 0x16332e,
  clientSoft: 0x16243a,
  platformSoft: 0x231e3a,
  floor: 0x0e121e,
};

const OWN = {
  gym: { fill: COLORS.gymSoft, stroke: COLORS.forest },
  client: { fill: COLORS.clientSoft, stroke: COLORS.client },
  platform: { fill: COLORS.platformSoft, stroke: COLORS.platform },
  done: { fill: COLORS.accent, stroke: COLORS.accent },
};

const RADII = { 1: 2.35, 2: 3.5, 3: 4.65 };
const RING_Y = { 1: 0.42, 2: 0.0, 3: -0.38 };

const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/** @type {Map<string, { item: object, stint: object, kind: string }>} */
const itemIndex = new Map();
for (const item of ROADMAP.foundation.items) {
  itemIndex.set(item.id, { item, stint: ROADMAP.foundation, kind: "foundation" });
}
if (ROADMAP.pullForward) {
  for (const item of ROADMAP.pullForward.items) {
    itemIndex.set(item.id, { item, stint: ROADMAP.pullForward, kind: "pull-forward" });
  }
}
for (const stint of ROADMAP.stints) {
  for (const item of stint.items) {
    itemIndex.set(item.id, { item, stint, kind: "stint" });
  }
}

function easeOutCubic(t) {
  return 1 - (1 - t) ** 3;
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

const canvas = document.getElementById("c");
const viewport = document.getElementById("viewport");
const dockEl = document.getElementById("dock");

const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  powerPreference: "high-performance",
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(viewport.clientWidth, viewport.clientHeight);
renderer.setClearColor(COLORS.paper, 1);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const labelRenderer = new CSS2DRenderer();
labelRenderer.setSize(viewport.clientWidth, viewport.clientHeight);
Object.assign(labelRenderer.domElement.style, {
  position: "absolute",
  inset: "0",
  pointerEvents: "none",
});
viewport.appendChild(labelRenderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(COLORS.paper);
scene.fog = new THREE.FogExp2(COLORS.paper, 0.024);

{
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  scene.environmentIntensity = 0.28;
  pmrem.dispose();
}

// Distant starfield — sparse, dim, no twinkle
{
  const count = 900;
  const positions = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) {
    // Random point on a shell between radius 26 and 44
    const r = 26 + Math.random() * 18;
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);
    positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
    positions[i * 3 + 1] = r * Math.cos(phi);
    positions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  const stars = new THREE.Points(
    geo,
    new THREE.PointsMaterial({
      color: COLORS.star,
      size: 0.05,
      sizeAttenuation: true,
      transparent: true,
      opacity: 0.7,
      fog: false,
      depthWrite: false,
    }),
  );
  scene.add(stars);
}

const camera = new THREE.PerspectiveCamera(
  34,
  viewport.clientWidth / viewport.clientHeight,
  0.1,
  80,
);
const camStart = new THREE.Vector3(0.2, 9.5, 0.4);
const camRest = new THREE.Vector3(6.4, 5.1, 7.6);
camera.position.copy(reduceMotion ? camRest : camStart);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.048;
controls.enablePan = false;
controls.minDistance = 5.8;
controls.maxDistance = 13.5;
controls.minPolarAngle = Math.PI * 0.2;
controls.maxPolarAngle = Math.PI * 0.46;
controls.autoRotate = false;
controls.autoRotateSpeed = 0.28;
controls.target.set(0, 0.15, 0);
controls.enabled = reduceMotion;

// Lighting — cool starlight key with a faint warm counter
const hemi = new THREE.HemisphereLight(0x8fa7d4, 0x0b0e16, 0.4);
scene.add(hemi);

const key = new THREE.DirectionalLight(0xf2ecdd, 1.0);
key.position.set(5.5, 10, 4);
key.castShadow = true;
key.shadow.mapSize.set(2048, 2048);
key.shadow.camera.near = 1;
key.shadow.camera.far = 24;
key.shadow.camera.left = -8;
key.shadow.camera.right = 8;
key.shadow.camera.top = 8;
key.shadow.camera.bottom = -8;
key.shadow.radius = 4;
key.shadow.bias = -0.0002;
scene.add(key);

const rim = new THREE.DirectionalLight(0x7fa8d9, 0.5);
rim.position.set(-6, 3, -4);
scene.add(rim);

const root = new THREE.Group();
scene.add(root);

/** Orbit groups rotate at slightly different rates */
const orbitGroups = [];

// Pedestal floor
{
  const floor = new THREE.Mesh(
    new THREE.CylinderGeometry(6.4, 6.55, 0.08, 96),
    new THREE.MeshPhysicalMaterial({
      color: COLORS.floor,
      roughness: 0.92,
      metalness: 0,
      clearcoat: 0.08,
      clearcoatRoughness: 0.7,
    }),
  );
  floor.position.y = -0.72;
  floor.receiveShadow = true;
  root.add(floor);

  const lip = new THREE.Mesh(
    new THREE.TorusGeometry(6.48, 0.012, 8, 128),
    new THREE.MeshStandardMaterial({
      color: COLORS.ring,
      roughness: 0.5,
      metalness: 0.3,
    }),
  );
  lip.rotation.x = Math.PI / 2;
  lip.position.y = -0.675;
  root.add(lip);

  // Soft under-glow disc (not bloom — a flat translucent plate)
  const wash = new THREE.Mesh(
    new THREE.CircleGeometry(2.2, 64),
    new THREE.MeshBasicMaterial({
      color: COLORS.accent,
      transparent: true,
      opacity: 0.07,
      depthWrite: false,
      side: THREE.DoubleSide,
    }),
  );
  wash.rotation.x = -Math.PI / 2;
  wash.position.y = -0.66;
  root.add(wash);
}

/** @type {THREE.Object3D[]} */
const pickables = [];
/** @type {Map<string, { mesh: THREE.Mesh, labelEl: HTMLElement, targetScale: number, hoverScale: number, mat: THREE.MeshPhysicalMaterial }>} */
const nodeRefs = new Map();
let selectedId = null;
let hoveredId = null;
/** @type {THREE.Group | null} */
let coreGroup = null;
/** @type {THREE.Mesh | null} */
let coreMesh = null;

function ownershipLabel(o) {
  if (o === "gym") return "Gym-owned";
  if (o === "client") return "Client-owned";
  if (o === "platform") return "Platform";
  if (o === "done") return "Shipped";
  return o;
}

function pulseDock() {
  dockEl.classList.remove("dock-in");
  void dockEl.offsetWidth;
  dockEl.classList.add("dock-in");
}

/** @type {{ title: string, detail: object, exit?: string | null } | null} */
let dockDetailPayload = null;

function setDock({ kicker, title, body, meta, exit, ownership, detail }) {
  dockEl.dataset.ownership = ownership || "gym";
  document.getElementById("dock-kicker").textContent = kicker;
  document.getElementById("dock-title").textContent = title;
  document.getElementById("dock-body").textContent = body;

  const metaEl = document.getElementById("dock-meta");
  const exitEl = document.getElementById("dock-exit");
  const detailBtn = document.getElementById("dock-detail-btn");

  if (meta && Object.keys(meta).length) {
    metaEl.hidden = false;
    metaEl.replaceChildren();
    for (const [k, v] of Object.entries(meta)) {
      const row = document.createElement("div");
      const dt = document.createElement("dt");
      dt.textContent = k;
      const dd = document.createElement("dd");
      dd.textContent = v;
      row.append(dt, dd);
      metaEl.appendChild(row);
    }
  } else {
    metaEl.hidden = true;
    metaEl.replaceChildren();
  }

  if (exit) {
    exitEl.hidden = false;
    exitEl.textContent = `Exit: ${exit}`;
  } else {
    exitEl.hidden = true;
    exitEl.textContent = "";
  }

  if (detail && typeof window.openReaderModal === "function") {
    dockDetailPayload = { title, detail, exit: exit || null };
    if (detailBtn) detailBtn.hidden = false;
  } else {
    dockDetailPayload = null;
    if (detailBtn) detailBtn.hidden = true;
  }

  pulseDock();
}

function openDockDetail() {
  if (!dockDetailPayload || typeof window.openReaderModal !== "function") return;
  const { title, detail, exit } = dockDetailPayload;
  window.openReaderModal({
    title,
    kicker: "Orbit · detailed view",
    showToc: true,
    sections: window.sectionsFromDetail(detail, { exit }),
  });
}

function selectFoundation() {
  selectedId = "foundation";
  syncSelectionScales();
  setDock({
    kicker: "Foundation · shipped",
    title: ROADMAP.foundation.title,
    body: ROADMAP.foundation.body,
    meta: {
      Modules: "M1 Identity · M2 Gym Org",
      Paths: "src/features/auth · src/features/gym-orgs",
      Status: "Done",
    },
    exit: null,
    ownership: "done",
    detail: ROADMAP.foundation.detail || null,
  });
  focusTarget(new THREE.Vector3(0, 0.35, 0));
  resumeAutoRotateSoon(2200);
}

function selectItem(id) {
  const entry = itemIndex.get(id);
  if (!entry) return;
  const { item, stint, kind } = entry;
  selectedId = id;
  syncSelectionScales();

  setDock({
    kicker: kind === "foundation" ? "Foundation" : `${stint.label} · ${stint.title}`,
    title: `${item.num}  ${item.title}`,
    body: item.body,
    meta: {
      PRD: item.prd,
      Paths: item.paths,
      Ownership: ownershipLabel(item.ownership),
      Status: item.status === "done" ? "Shipped" : "Todo",
    },
    exit: kind === "stint" || kind === "pull-forward" ? stint.exit : null,
    ownership: item.status === "done" ? "done" : item.ownership,
    detail: item.detail || null,
  });

  const ref = nodeRefs.get(id);
  if (ref) {
    const p = new THREE.Vector3();
    ref.mesh.getWorldPosition(p);
    focusTarget(p);
  }
  resumeAutoRotateSoon(5000);
}

let focusAnim = null;
function focusTarget(worldPoint) {
  if (reduceMotion) {
    controls.target.copy(worldPoint.clone().setY(worldPoint.y * 0.35));
    return;
  }
  const from = controls.target.clone();
  const to = worldPoint.clone().multiplyScalar(0.22);
  to.y = lerp(0.1, worldPoint.y * 0.45, 0.6);
  focusAnim = { from, to, t: 0, dur: 0.85 };
  controls.autoRotate = false;
}

function resumeAutoRotateSoon(ms) {
  clearTimeout(resumeAutoRotateSoon._t);
  if (reduceMotion) return;
  resumeAutoRotateSoon._t = setTimeout(() => {
    if (intro.done) controls.autoRotate = true;
  }, ms);
}

function syncSelectionScales() {
  for (const [id, ref] of nodeRefs) {
    const on = id === selectedId;
    const hover = id === hoveredId;
    ref.labelEl.classList.toggle("is-selected", on);
    ref.targetScale = on ? 1.32 : hover ? 1.14 : 1;
    ref.mat.emissiveIntensity = on ? 0.85 : hover ? 0.45 : 0.2;
  }
  if (coreMesh) {
    const on = selectedId === "foundation";
    coreMesh.userData.targetScale = on ? 1.06 : hoveredId === "foundation" ? 1.03 : 1;
  }
}

// —— Core sculpture ——
{
  coreGroup = new THREE.Group();
  coreGroup.position.y = 0.15;

  coreMesh = new THREE.Mesh(
    new THREE.SphereGeometry(0.78, 64, 48),
    new THREE.MeshPhysicalMaterial({
      color: COLORS.accent,
      roughness: 0.28,
      metalness: 0.08,
      clearcoat: 0.55,
      clearcoatRoughness: 0.25,
      sheen: 0.35,
      sheenRoughness: 0.5,
      sheenColor: new THREE.Color(0xfff2d8),
      emissive: new THREE.Color(COLORS.accent),
      emissiveIntensity: 0.28,
    }),
  );
  coreMesh.castShadow = true;
  coreMesh.receiveShadow = true;
  coreMesh.userData = { id: "foundation", kind: "foundation", targetScale: 1 };
  coreGroup.add(coreMesh);

  const equator = new THREE.Mesh(
    new THREE.TorusGeometry(0.82, 0.022, 16, 96),
    new THREE.MeshPhysicalMaterial({
      color: COLORS.ring,
      roughness: 0.35,
      metalness: 0.45,
      clearcoat: 0.4,
    }),
  );
  equator.rotation.x = Math.PI / 2;
  equator.castShadow = true;
  coreGroup.add(equator);

  // Nested meridian — quiet elegance
  const meridian = new THREE.Mesh(
    new THREE.TorusGeometry(0.82, 0.01, 12, 96),
    new THREE.MeshStandardMaterial({
      color: COLORS.ring,
      roughness: 0.45,
      metalness: 0.3,
      transparent: true,
      opacity: 0.55,
    }),
  );
  meridian.rotation.y = Math.PI / 2;
  coreGroup.add(meridian);

  const pedestal = new THREE.Mesh(
    new THREE.CylinderGeometry(0.28, 0.38, 0.55, 32),
    new THREE.MeshPhysicalMaterial({
      color: 0x1a2134,
      roughness: 0.7,
      metalness: 0.1,
    }),
  );
  pedestal.position.y = -0.55;
  pedestal.castShadow = true;
  pedestal.receiveShadow = true;
  coreGroup.add(pedestal);

  const labelDiv = document.createElement("div");
  labelDiv.className = "label3d label-core";
  labelDiv.textContent = "CORE";
  const label = new CSS2DObject(labelDiv);
  label.position.set(0, 1.05, 0);
  coreGroup.add(label);

  root.add(coreGroup);
  pickables.push(coreMesh);
}

function makeRingMaterial(opacity = 1) {
  return new THREE.MeshPhysicalMaterial({
    color: COLORS.ring,
    roughness: 0.45,
    metalness: 0.35,
    clearcoat: 0.3,
    transparent: opacity < 1,
    opacity,
  });
}

function makeArc(radius, fraction, y, color) {
  const points = [];
  const segs = Math.max(12, Math.floor(80 * fraction));
  for (let i = 0; i <= segs; i++) {
    const t = (i / segs) * fraction * Math.PI * 2 - Math.PI / 2;
    points.push(new THREE.Vector3(Math.cos(t) * radius, 0, Math.sin(t) * radius));
  }
  const geo = new THREE.TubeGeometry(
    new THREE.CatmullRomCurve3(points),
    segs,
    0.028,
    8,
    false,
  );
  const mesh = new THREE.Mesh(
    geo,
    new THREE.MeshPhysicalMaterial({
      color,
      roughness: 0.3,
      metalness: 0.15,
      clearcoat: 0.4,
      emissive: new THREE.Color(color),
      emissiveIntensity: 0.12,
    }),
  );
  mesh.position.y = y;
  mesh.castShadow = true;
  return mesh;
}

// —— Rings + nodes ——
for (const stint of ROADMAP.stints) {
  const r = RADII[stint.orbit];
  const y = RING_Y[stint.orbit];
  const group = new THREE.Group();
  group.position.y = y;
  group.userData.spin = 0.04 + stint.orbit * 0.012;
  orbitGroups.push(group);
  root.add(group);

  // Dual hairline rings
  const outer = new THREE.Mesh(new THREE.TorusGeometry(r, 0.014, 12, 160), makeRingMaterial(0.85));
  outer.rotation.x = Math.PI / 2;
  outer.castShadow = true;
  group.add(outer);

  const inner = new THREE.Mesh(
    new THREE.TorusGeometry(r - 0.08, 0.006, 8, 160),
    makeRingMaterial(0.35),
  );
  inner.rotation.x = Math.PI / 2;
  group.add(inner);

  const doneFrac =
    stint.items.filter((i) => i.status === "done").length / stint.items.length;
  if (doneFrac > 0) group.add(makeArc(r, doneFrac, 0.01, COLORS.accent));

  // Orbit index tick mark
  const tick = document.createElement("div");
  tick.className = "label3d label-orbit";
  tick.textContent = `ORBIT ${stint.orbit}`;
  const tickObj = new CSS2DObject(tick);
  tickObj.position.set(0, 0.02, -r);
  group.add(tickObj);

  const n = stint.items.length;
  const start = stint.orbit === 1 ? -0.4 : stint.orbit === 2 ? 0.25 : -0.15;
  const sweep = Math.PI * 1.72;

  stint.items.forEach((item, i) => {
    const angle = start + (sweep / Math.max(n - 1, 1)) * i;
    const x = Math.cos(angle) * r;
    const z = Math.sin(angle) * r;
    const ownKey = item.status === "done" ? "done" : item.ownership;
    const own = OWN[ownKey];

    const node = new THREE.Group();
    node.position.set(x, 0, z);

    // Stem — connects node to ring plane
    const stem = new THREE.Mesh(
      new THREE.CylinderGeometry(0.012, 0.012, 0.22, 8),
      new THREE.MeshStandardMaterial({
        color: own.stroke,
        roughness: 0.55,
        metalness: 0.1,
        transparent: true,
        opacity: 0.45,
      }),
    );
    stem.position.y = -0.14;
    node.add(stem);

    const mat = new THREE.MeshPhysicalMaterial({
      color: own.fill,
      roughness: 0.32,
      metalness: 0.12,
      clearcoat: 0.45,
      clearcoatRoughness: 0.3,
      emissive: new THREE.Color(own.stroke),
      emissiveIntensity: 0.2,
    });

    const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.155, 32, 24), mat);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    mesh.userData = { id: item.id, kind: "stint" };
    node.add(mesh);

    const band = new THREE.Mesh(
      new THREE.TorusGeometry(0.195, 0.016, 10, 40),
      new THREE.MeshPhysicalMaterial({
        color: own.stroke,
        roughness: 0.4,
        metalness: 0.3,
        clearcoat: 0.35,
      }),
    );
    band.rotation.x = Math.PI / 2;
    mesh.add(band);

    if (ownKey === "client") {
      const dash = new THREE.Mesh(
        new THREE.TorusGeometry(0.235, 0.008, 8, 28),
        new THREE.MeshBasicMaterial({
          color: own.stroke,
          transparent: true,
          opacity: 0.55,
        }),
      );
      dash.rotation.x = Math.PI / 2;
      mesh.add(dash);
    }

    const labelDiv = document.createElement("div");
    labelDiv.className = "label3d";
    labelDiv.textContent = item.num;
    const label = new CSS2DObject(labelDiv);
    label.position.set(0, 0.34, 0);
    mesh.add(label);

    group.add(node);
    pickables.push(mesh);
    nodeRefs.set(item.id, {
      mesh,
      labelEl: labelDiv,
      targetScale: 1,
      hoverScale: 1,
      mat,
    });
  });
}

// —— Interaction ——
const raycaster = new THREE.Raycaster();
const pointer = new THREE.Vector2();
let pointerDown = null;

function ndcFromEvent(e) {
  const rect = renderer.domElement.getBoundingClientRect();
  pointer.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  pointer.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
}

function pickId() {
  raycaster.setFromCamera(pointer, camera);
  const hits = raycaster.intersectObjects(pickables, false);
  return hits.length ? hits[0].object.userData.id : null;
}

renderer.domElement.addEventListener("pointerdown", (e) => {
  pointerDown = { x: e.clientX, y: e.clientY };
});

renderer.domElement.addEventListener("pointerup", (e) => {
  if (!pointerDown) return;
  const dx = e.clientX - pointerDown.x;
  const dy = e.clientY - pointerDown.y;
  pointerDown = null;
  if (dx * dx + dy * dy > 16) return;

  ndcFromEvent(e);
  const id = pickId();
  if (!id || id === "foundation") selectFoundation();
  else selectItem(id);
});

renderer.domElement.addEventListener("pointermove", (e) => {
  ndcFromEvent(e);
  const id = pickId();
  if (id !== hoveredId) {
    hoveredId = id;
    syncSelectionScales();
  }
  renderer.domElement.style.cursor = id ? "pointer" : "grab";
});

function onResize() {
  const w = viewport.clientWidth;
  const h = viewport.clientHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  labelRenderer.setSize(w, h);
}
window.addEventListener("resize", onResize);

// Intro camera
const intro = {
  done: reduceMotion,
  t: 0,
  dur: 2.4,
};

const clock = new THREE.Clock();

function tick() {
  const dt = Math.min(clock.getDelta(), 0.05);
  const t = clock.elapsedTime;

  if (!intro.done) {
    intro.t += dt;
    const u = easeOutCubic(Math.min(1, intro.t / intro.dur));
    camera.position.lerpVectors(camStart, camRest, u);
    if (u >= 1) {
      intro.done = true;
      controls.enabled = true;
      if (!reduceMotion) controls.autoRotate = true;
      document.body.classList.add("ready");
    }
  }

  if (focusAnim) {
    focusAnim.t += dt;
    const u = easeOutCubic(Math.min(1, focusAnim.t / focusAnim.dur));
    controls.target.lerpVectors(focusAnim.from, focusAnim.to, u);
    if (u >= 1) focusAnim = null;
  }

  if (!reduceMotion) {
    for (const g of orbitGroups) {
      g.rotation.y += g.userData.spin * dt;
    }
    if (coreGroup) {
      coreGroup.rotation.y = t * 0.12;
      coreGroup.position.y = 0.15 + Math.sin(t * 0.65) * 0.035;
    }
  }

  for (const ref of nodeRefs.values()) {
    const s = lerp(ref.mesh.scale.x, ref.targetScale, 1 - Math.exp(-10 * dt));
    ref.mesh.scale.setScalar(s);
  }
  if (coreMesh) {
    const target = coreMesh.userData.targetScale ?? 1;
    const s = lerp(coreMesh.scale.x, target, 1 - Math.exp(-8 * dt));
    coreMesh.scale.setScalar(s);
  }

  controls.update();
  renderer.render(scene, camera);
  labelRenderer.render(scene, camera);
  requestAnimationFrame(tick);
}

document.getElementById("dock-detail-btn")?.addEventListener("click", openDockDetail);
selectFoundation();
if (reduceMotion) document.body.classList.add("ready");
tick();

/* Shared large reading modal — Product + Orbit 2D/3D */

.reader-modal {
  position: fixed;
  inset: 0;
  z-index: 4000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.25rem;
  background: rgba(18, 21, 26, 0.55);
  backdrop-filter: blur(4px);
}

.reader-modal[hidden] {
  display: none !important;
}

.reader-modal__panel {
  width: min(920px, 94vw);
  height: min(88vh, 900px);
  max-height: 88vh;
  display: flex;
  flex-direction: column;
  background: #fafbfa;
  border: 1px solid #d5dae0;
  box-shadow: 0 24px 64px rgba(18, 21, 26, 0.28);
  color: #12151a;
}

.reader-modal__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.1rem 1.35rem;
  border-bottom: 1px solid #d5dae0;
  background: #f3f5f4;
  flex-shrink: 0;
}

.reader-modal__kicker {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #6b7380;
  margin-bottom: 0.25rem;
}

.reader-modal__title {
  font-family: "Bricolage Grotesque", "Space Grotesk", sans-serif;
  font-size: clamp(1.15rem, 2.2vw, 1.45rem);
  font-weight: 700;
  line-height: 1.2;
  color: #12151a;
}

.reader-modal__close {
  appearance: none;
  border: 1px solid #d5dae0;
  background: #fff;
  color: #3a414c;
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.75rem;
  letter-spacing: 0.04em;
  padding: 0.55rem 0.75rem;
  cursor: pointer;
  flex-shrink: 0;
}

.reader-modal__close:hover {
  border-color: #0f5c4c;
  color: #12151a;
}

.reader-modal__layout {
  display: grid;
  grid-template-columns: 1fr;
  min-height: 0;
  flex: 1;
}

.reader-modal__layout.has-toc {
  grid-template-columns: minmax(160px, 220px) 1fr;
}

.reader-modal__toc {
  border-right: 1px solid #d5dae0;
  padding: 1rem 0.85rem;
  overflow: auto;
  background: #f3f5f4;
}

.reader-modal__toc[hidden] {
  display: none !important;
}

.reader-modal__toc p {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.65rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #6b7380;
  margin: 0 0 0.65rem 0.35rem;
}

.reader-modal__toc a {
  display: block;
  font-size: 0.82rem;
  color: #3a414c;
  text-decoration: none;
  padding: 0.4rem 0.5rem;
  border-left: 2px solid transparent;
  line-height: 1.35;
}

.reader-modal__toc a:hover {
  color: #0f5c4c;
  background: rgba(15, 92, 76, 0.06);
}

.reader-modal__body {
  overflow: auto;
  padding: 1.35rem 1.5rem 2rem;
  -webkit-overflow-scrolling: touch;
}

.reader-modal__body h3 {
  font-family: "Space Grotesk", sans-serif;
  font-size: 1.1rem;
  font-weight: 700;
  margin: 1.75rem 0 0.65rem;
  color: #0f5c4c;
  scroll-margin-top: 0.75rem;
}

.reader-modal__body h3:first-child {
  margin-top: 0;
}

.reader-modal__body p {
  font-size: 0.98rem;
  line-height: 1.65;
  color: #3a414c;
  margin: 0 0 0.85rem;
}

.reader-modal__body ul,
.reader-modal__body ol {
  margin: 0 0 1rem 1.15rem;
  color: #3a414c;
}

.reader-modal__body li {
  margin-bottom: 0.4rem;
  line-height: 1.55;
  font-size: 0.95rem;
}

.reader-modal__body table {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 1.25rem;
  font-size: 0.88rem;
}

.reader-modal__body th,
.reader-modal__body td {
  border: 1px solid #d5dae0;
  padding: 0.45rem 0.6rem;
  text-align: left;
  vertical-align: top;
}

.reader-modal__body th {
  background: #f3f5f4;
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.72rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #6b7380;
}

.reader-modal__body .meta-line {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.75rem;
  color: #6b7380;
  margin-bottom: 1rem;
}

body.reader-modal-open {
  overflow: hidden;
}

@media (max-width: 720px) {
  .reader-modal {
    padding: 0.5rem;
  }

  .reader-modal__panel {
    width: 100%;
    height: 94vh;
    max-height: 94vh;
  }

  .reader-modal__layout.has-toc {
    grid-template-columns: 1fr;
  }

  .reader-modal__toc {
    border-right: none;
    border-bottom: 1px solid #d5dae0;
    max-height: 140px;
  }
}

:root {
  --ink: #12151a;
  --ink-soft: #3a414c;
  --muted: #6b7380;
  --line: #d5dae0;
  --paper: #f3f5f4;
  --paper-2: #e7ebe9;
  --surface: #fafbfa;
  --accent: #b8f000;
  --accent-ink: #1a2e00;
  --forest: #0f5c4c;
  --forest-soft: #d8efe8;
  --warn-bg: #fff1e8;
  --warn-ink: #8a3b12;
  --radius: 2px;
  --max: 1120px;
  --nav-h: 64px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: "IBM Plex Sans", sans-serif;
  color: var(--ink);
  background: var(--paper);
  line-height: 1.5;
  font-size: 16px;
}

/* Blueprint grid atmosphere */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(243,245,244,0.92) 0%, rgba(243,245,244,0.75) 40%, rgba(243,245,244,0.95) 100%),
    linear-gradient(90deg, transparent 0, transparent calc(100% - 1px), var(--line) calc(100% - 1px)),
    linear-gradient(transparent 0, transparent calc(100% - 1px), var(--line) calc(100% - 1px)),
    radial-gradient(ellipse 80% 50% at 10% -10%, #d8efe8 0%, transparent 55%),
    radial-gradient(ellipse 60% 40% at 100% 0%, #e8f5c8 0%, transparent 50%),
    repeating-linear-gradient(
      -12deg,
      transparent,
      transparent 40px,
      rgba(15, 92, 76, 0.03) 40px,
      rgba(15, 92, 76, 0.03) 41px
    );
  background-size:
    auto,
    48px 48px,
    48px 48px,
    auto,
    auto,
    auto;
}

a { color: var(--forest); text-decoration-thickness: 1px; text-underline-offset: 3px; }
a:hover { color: var(--ink); }

.wrap { width: min(100% - 2.5rem, var(--max)); margin-inline: auto; }

/* Nav */
.nav {
  position: sticky;
  top: 0;
  z-index: 50;
  height: var(--nav-h);
  display: flex;
  align-items: center;
  backdrop-filter: blur(12px);
  background: rgba(243, 245, 244, 0.82);
  border-bottom: 1px solid var(--line);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: min(100% - 2.5rem, var(--max));
  margin-inline: auto;
}
.brand {
  font-family: "Bricolage Grotesque", sans-serif;
  font-weight: 800;
  font-size: 1.05rem;
  letter-spacing: -0.03em;
  color: var(--ink);
  text-decoration: none;
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
}
.brand span {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.68rem;
  font-weight: 500;
  color: var(--muted);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.nav-links {
  display: flex;
  gap: 0.25rem;
  list-style: none;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.nav-links a {
  text-decoration: none;
  color: var(--ink-soft);
  font-size: 0.82rem;
  font-weight: 500;
  padding: 0.4rem 0.65rem;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--ink);
  border-bottom-color: var(--accent);
}

/* Hero */
.hero {
  min-height: calc(100dvh - var(--nav-h));
  display: grid;
  align-items: end;
  padding: 3rem 0 4rem;
  position: relative;
  overflow: hidden;
}
.hero-visual {
  position: absolute;
  inset: 8% 0 auto auto;
  width: min(52vw, 560px);
  height: min(70vh, 640px);
  pointer-events: none;
  opacity: 0.9;
  mask-image: linear-gradient(90deg, transparent, #000 18%, #000 100%);
}
.hero-visual svg { width: 100%; height: 100%; }
.hero-copy {
  position: relative;
  z-index: 1;
  max-width: 34rem;
  animation: rise 0.8s ease both;
}
@keyframes rise {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}
.hero h1 {
  font-family: "Bricolage Grotesque", sans-serif;
  font-weight: 800;
  font-size: clamp(2.6rem, 7vw, 4.6rem);
  line-height: 0.95;
  letter-spacing: -0.045em;
  margin: 0.35rem 0 1rem;
}
.hero p {
  font-size: 1.08rem;
  color: var(--ink-soft);
  max-width: 28rem;
  margin-bottom: 1.75rem;
}
.cta {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  background: var(--ink);
  color: var(--accent);
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-decoration: none;
  padding: 0.95rem 1.25rem;
  border: none;
  cursor: pointer;
  transition: transform 0.2s ease, background 0.2s ease;
}
.cta:hover {
  background: var(--forest);
  color: #fff;
  transform: translateY(-2px);
}
.cta svg { width: 14px; height: 14px; }

/* Sections */
section {
  padding: 4.5rem 0;
  border-top: 1px solid var(--line);
}
.sec-label {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.72rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--forest);
  margin-bottom: 0.65rem;
}
.sec-title {
  font-family: "Bricolage Grotesque", sans-serif;
  font-weight: 700;
  font-size: clamp(1.7rem, 3.5vw, 2.35rem);
  letter-spacing: -0.03em;
  line-height: 1.1;
  margin-bottom: 0.65rem;
}
.sec-lead {
  color: var(--ink-soft);
  max-width: 36rem;
  margin-bottom: 2.25rem;
}

/* Positioning */
.pos-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
}
.pos-item {
  background: var(--surface);
  padding: 1.25rem 1.1rem 1.4rem;
  min-height: 8.5rem;
}
.pos-item strong {
  display: block;
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.68rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 0.55rem;
}
.pos-item p {
  font-family: "Bricolage Grotesque", sans-serif;
  font-weight: 700;
  font-size: 1.05rem;
  letter-spacing: -0.02em;
  line-height: 1.25;
}

/* Surfaces */
.surfaces {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}
.surface {
  padding: 1.5rem 1.35rem;
  border: 1px solid var(--line);
  background: var(--surface);
  position: relative;
  overflow: hidden;
  transition: border-color 0.25s ease;
}
.surface:hover { border-color: var(--forest); }
.surface::after {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
  background: var(--accent);
  transform: scaleY(0);
  transform-origin: top;
  transition: transform 0.35s ease;
}
.surface:hover::after { transform: scaleY(1); }
.surface .code {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.7rem;
  color: var(--muted);
  margin-bottom: 0.5rem;
}
.surface h3 {
  font-family: "Bricolage Grotesque", sans-serif;
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 0.4rem;
}
.surface p { color: var(--ink-soft); font-size: 0.92rem; }

/* Modules */
.mod-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
  align-items: center;
}
.filter-btn {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.72rem;
  font-weight: 500;
  padding: 0.45rem 0.75rem;
  border: 1px solid var(--line);
  background: var(--surface);
  color: var(--ink-soft);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}
.filter-btn:hover,
.filter-btn.active {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--accent);
}
.mod-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 0.75rem;
}
.mod {
  border: 1px solid var(--line);
  background: var(--surface);
  text-align: left;
  cursor: pointer;
  padding: 0;
  font: inherit;
  color: inherit;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  animation: rise 0.5s ease both;
}
.mod:nth-child(1) { animation-delay: 0.02s; }
.mod:nth-child(2) { animation-delay: 0.04s; }
.mod:nth-child(3) { animation-delay: 0.06s; }
.mod:nth-child(4) { animation-delay: 0.08s; }
.mod:nth-child(5) { animation-delay: 0.1s; }
.mod:nth-child(6) { animation-delay: 0.12s; }
.mod:nth-child(7) { animation-delay: 0.14s; }
.mod:nth-child(8) { animation-delay: 0.16s; }
.mod:nth-child(9) { animation-delay: 0.18s; }
.mod:nth-child(10) { animation-delay: 0.2s; }
.mod:nth-child(11) { animation-delay: 0.22s; }
.mod:nth-child(12) { animation-delay: 0.24s; }
.mod:nth-child(13) { animation-delay: 0.26s; }
.mod:hover { border-color: var(--forest); }
.mod.open {
  border-color: var(--ink);
  grid-column: 1 / -1;
}
.mod-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 1.1rem 1.15rem;
  width: 100%;
}
.mod-id {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.7rem;
  font-weight: 500;
  color: var(--forest);
  margin-bottom: 0.25rem;
}
.mod-name {
  font-family: "Bricolage Grotesque", sans-serif;
  font-weight: 700;
  font-size: 1.12rem;
  letter-spacing: -0.02em;
  line-height: 1.2;
}
.mod-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
  margin-top: 0.55rem;
}
.tag {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.62rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 0.2rem 0.4rem;
  background: var(--paper-2);
  color: var(--ink-soft);
}
.tag.client { background: var(--forest-soft); color: var(--forest); }
.tag.trainer { background: #e8eef8; color: #2a4a7a; }
.tag.admin { background: #f0ecd8; color: #5c4a18; }
.chev {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  background: var(--paper);
  transition: transform 0.25s ease, background 0.2s;
}
.mod.open .chev {
  transform: rotate(45deg);
  background: var(--accent);
  border-color: var(--accent-ink);
}
.mod-body {
  display: none;
  padding: 0 1.15rem 1.25rem;
  border-top: 1px solid var(--line);
}
.mod.open .mod-body { display: block; animation: rise 0.3s ease both; }
.mod-summary {
  padding-top: 1rem;
  font-size: 0.98rem;
  color: var(--ink);
  line-height: 1.55;
  max-width: 52rem;
}
.mod-personas {
  margin-top: 0.5rem;
  font-size: 0.88rem;
  color: var(--ink-soft);
}
.mod-how-label {
  margin-top: 1rem;
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}
.mod-how {
  margin: 0.45rem 0 0 1.1rem;
  max-width: 48rem;
}
.mod-how li {
  font-size: 0.9rem;
  color: var(--ink-soft);
  margin-bottom: 0.35rem;
  padding-left: 0;
}
.mod-how li::before { display: none; }
.mod-actions {
  margin-top: 1.1rem;
  padding-top: 0.85rem;
  border-top: 1px dashed var(--line);
}
.mod-detail-btn {
  display: inline-block;
  cursor: pointer;
}
.mod-body ul {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 0.45rem 1.25rem;
  padding-top: 1rem;
}
.mod-body li {
  font-size: 0.9rem;
  color: var(--ink-soft);
  padding-left: 0.85rem;
  position: relative;
}
.mod-body li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 6px;
  height: 6px;
  background: var(--accent);
}
.mod-body li.out {
  color: var(--muted);
  text-decoration: line-through;
  text-decoration-color: var(--line);
}
.mod-body li.out::before { background: var(--line); }
.mod.hidden { display: none; }

/* Matrix */
.matrix-wrap {
  overflow-x: auto;
  border: 1px solid var(--line);
  background: var(--surface);
}
table.matrix {
  width: 100%;
  border-collapse: collapse;
  min-width: 640px;
  font-size: 0.88rem;
}
.matrix th,
.matrix td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--line);
  text-align: left;
}
.matrix th {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.68rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  background: var(--paper-2);
  position: sticky;
  top: 0;
}
.matrix td:first-child {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.78rem;
  white-space: nowrap;
}
.matrix tr:last-child td { border-bottom: none; }
.matrix tr:hover td { background: rgba(184, 240, 0, 0.08); }
.dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  background: var(--forest);
  vertical-align: middle;
  margin-right: 0.35rem;
}
.dot.soft { background: var(--muted); opacity: 0.5; }

/* Stack */
.stack-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
}
.stack-item {
  background: var(--ink);
  color: #e8ece9;
  padding: 1.5rem 1.25rem;
  min-height: 7.5rem;
}
.stack-item .code {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.68rem;
  color: var(--accent);
  margin-bottom: 0.45rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.stack-item h3 {
  font-family: "Bricolage Grotesque", sans-serif;
  font-weight: 700;
  font-size: 1.2rem;
  letter-spacing: -0.02em;
  margin-bottom: 0.35rem;
}
.stack-item p { font-size: 0.85rem; color: #9aa3ad; }

/* Out */
.out-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.out-chip {
  font-size: 0.85rem;
  color: var(--warn-ink);
  background: var(--warn-bg);
  padding: 0.45rem 0.75rem;
  border: 1px solid #f0d0bc;
}

/* Footer */
footer {
  padding: 2.5rem 0 3.5rem;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.88rem;
}
footer .foot-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 1rem;
  align-items: baseline;
}
footer strong {
  font-family: "Bricolage Grotesque", sans-serif;
  color: var(--ink);
  font-weight: 700;
}

@media (max-width: 960px) {
  .pos-grid { grid-template-columns: repeat(2, 1fr); }
  .pos-item:last-child { grid-column: 1 / -1; }
  .surfaces { grid-template-columns: 1fr; }
  .stack-row { grid-template-columns: 1fr 1fr; }
  .hero-visual {
    opacity: 0.35;
    width: 70vw;
    inset: 0 0 auto auto;
    mask-image: linear-gradient(180deg, #000 30%, transparent 85%);
  }
}
@media (max-width: 560px) {
  .wrap, .nav-inner { width: min(100% - 1.5rem, var(--max)); }
  .pos-grid { grid-template-columns: 1fr; }
  .stack-row { grid-template-columns: 1fr; }
  .nav-links { display: none; }
  .hero { min-height: auto; padding-top: 2.5rem; padding-bottom: 3rem; }
}

/* ── Site tabs (Product | Roles) ───────────────────────────── */
.nav-center {
  display: flex;
  align-items: center;
  gap: 1.25rem;
  min-width: 0;
  flex: 1;
  justify-content: flex-end;
}

.site-tabs {
  display: inline-flex;
  gap: 0;
  border: 1px solid var(--line);
  background: var(--surface);
  flex-shrink: 0;
}

.site-tab {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.72rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 0.45rem 0.85rem;
  border: none;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.site-tab:hover { color: var(--ink); }

.site-tab.is-active {
  background: var(--ink);
  color: var(--accent);
}

.view[hidden] { display: none !important; }
.view.is-active { display: block; }
.nav-links[hidden],
.nav-links.is-hidden { display: none !important; }

.cta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: center;
}

.cta-ghost {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--ink-soft);
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  padding: 0.95rem 1.25rem;
  cursor: pointer;
  text-decoration: none;
  transition: border-color 0.15s ease, color 0.15s ease;
}

.cta-ghost:hover {
  border-color: var(--forest);
  color: var(--ink);
}

button.cta-ghost { appearance: none; }

/* ── Roles tab ────────────────────────────────────────────── */
.hero-roles {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 2rem;
  align-items: center;
  overflow: visible;
}

.hero-roles .hero-copy {
  max-width: none;
  animation: rise 0.8s ease both;
}

.hero-roles .lede {
  font-size: 1.08rem;
  color: var(--ink-soft);
  max-width: 34rem;
  margin-bottom: 1.75rem;
}

.roles-ladder {
  justify-self: end;
  width: min(100%, 420px);
  animation: rise 0.8s ease-out both;
}

.ladder-svg {
  width: 100%;
  height: auto;
  filter: drop-shadow(0 12px 28px rgba(15, 92, 76, 0.08));
}

.svg-label {
  fill: var(--forest);
  fill-opacity: 0.7;
  font-family: "IBM Plex Mono", monospace;
  font-size: 11px;
  letter-spacing: 0.06em;
}

.svg-node, .svg-node-sm {
  fill: var(--ink);
  font-family: "IBM Plex Mono", monospace;
  font-size: 12px;
  font-weight: 500;
}

.svg-node-sm { font-size: 10px; }

.svg-hint {
  fill: var(--muted);
  font-family: "IBM Plex Sans", sans-serif;
  font-size: 10px;
}

.lane-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.lane-card {
  padding: 1.5rem 1.6rem;
  border: 1px solid var(--line);
  background: var(--surface);
  animation: rise 0.6s ease-out both;
}

.lane-client { border-top: 3px solid #2f6fed; }
.lane-staff { border-top: 3px solid var(--accent); animation-delay: 0.08s; }

.lane-kicker {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 0.35rem;
}

.lane-card h3 {
  font-family: "Bricolage Grotesque", sans-serif;
  font-size: 1.5rem;
  letter-spacing: -0.03em;
  margin-bottom: 0.5rem;
}

.lane-card p { color: var(--ink-soft); margin-bottom: 1rem; font-size: 0.95rem; }

.lane-card ul {
  list-style: none;
  display: grid;
  gap: 0.4rem;
}

.lane-card li {
  font-size: 0.88rem;
  padding-left: 1rem;
  position: relative;
}

.lane-card li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 6px;
  height: 6px;
  background: var(--accent);
}

.lane-client li::before { background: #2f6fed; }

.role-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.75rem;
  margin-bottom: 1.25rem;
}

.role-card {
  text-align: left;
  padding: 1.15rem 1.1rem;
  border: 1px solid var(--line);
  background: var(--surface);
  cursor: pointer;
  transition: border-color 0.2s ease, transform 0.2s ease, background 0.2s ease;
  font: inherit;
  color: inherit;
  width: 100%;
}

.role-card:hover {
  transform: translateY(-3px);
  border-color: var(--forest);
}

.role-card.is-active {
  border-color: var(--forest);
  box-shadow: inset 0 0 0 1px var(--forest);
}

.role-card .code {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.7rem;
  letter-spacing: 0.04em;
  color: var(--muted);
  margin-bottom: 0.35rem;
}

.role-card h3 {
  font-family: "Bricolage Grotesque", sans-serif;
  font-size: 1.15rem;
  letter-spacing: -0.02em;
  margin-bottom: 0.35rem;
}

.role-card .lane-pill {
  display: inline-block;
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.65rem;
  letter-spacing: 0.06em;
  padding: 0.15rem 0.4rem;
  margin-bottom: 0.55rem;
  text-transform: uppercase;
}

.role-card[data-color="client"] .lane-pill { background: rgba(47, 111, 237, 0.12); color: #2f6fed; }
.role-card[data-color="unassigned"] .lane-pill { background: rgba(92, 83, 70, 0.12); color: #5c5346; }
.role-card[data-color="trainer"] .lane-pill { background: var(--forest-soft); color: var(--forest); }
.role-card[data-color="admin"] .lane-pill { background: rgba(184, 240, 0, 0.35); color: var(--accent-ink); }

.role-card .count { font-size: 0.82rem; color: var(--ink-soft); }

.role-card.is-active[data-color="client"] { background: rgba(47, 111, 237, 0.12); }
.role-card.is-active[data-color="unassigned"] { background: rgba(92, 83, 70, 0.12); }
.role-card.is-active[data-color="trainer"] { background: var(--forest-soft); }
.role-card.is-active[data-color="admin"] { background: rgba(184, 240, 0, 0.35); }

.role-detail {
  min-height: 1.5em;
  color: var(--ink-soft);
  font-size: 0.95rem;
  max-width: 42rem;
}

.perm-matrix-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 1.5rem;
  flex-wrap: wrap;
  margin-bottom: 0.5rem;
}

.perm-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.perm-filter {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 0.4rem 0.65rem;
  border: 1px solid var(--line);
  background: var(--surface);
  color: var(--ink-soft);
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.perm-filter:hover,
.perm-filter.is-active {
  border-color: var(--forest);
  color: var(--ink);
  background: var(--forest-soft);
}

.perm-filter[data-role="ALL"].is-active {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
}

.perm-matrix-scroll {
  overflow-x: auto;
  border: 1px solid var(--line);
  background: var(--surface);
  margin-top: 1.25rem;
}

table.perm-matrix {
  width: 100%;
  border-collapse: collapse;
  min-width: 640px;
  font-size: 0.88rem;
}

.perm-matrix th,
.perm-matrix td {
  padding: 0.7rem 0.85rem;
  border-bottom: 1px solid var(--line);
  text-align: center;
  vertical-align: middle;
}

.perm-matrix th:first-child,
.perm-matrix td:first-child {
  text-align: left;
  position: sticky;
  left: 0;
  background: var(--surface);
  z-index: 1;
  min-width: 11rem;
}

.perm-matrix thead th {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.68rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--muted);
  background: var(--paper-2);
}

.perm-matrix thead th:first-child { background: var(--paper-2); }

.perm-matrix .perm-code {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.78rem;
  color: var(--ink);
  display: block;
}

.perm-matrix .perm-label {
  font-size: 0.75rem;
  color: var(--muted);
}

.perm-matrix .group-row td {
  text-align: left;
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--forest);
  background: var(--forest-soft);
  padding: 0.45rem 0.85rem;
}

.perm-matrix .cell {
  display: inline-flex;
  width: 1.35rem;
  height: 1.35rem;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  transition: transform 0.2s ease, opacity 0.2s ease;
}

.perm-matrix .cell.on {
  background: var(--accent);
  color: var(--accent-ink);
  box-shadow: 0 0 0 1px rgba(26, 46, 0, 0.15);
}

.perm-matrix .cell.on svg { width: 11px; height: 11px; }

.perm-matrix .cell.off {
  background: transparent;
  border: 1px solid var(--line);
  opacity: 0.55;
}

.perm-matrix tr.is-dimmed { opacity: 0.28; }
.perm-matrix tr.is-highlight .cell.on { transform: scale(1.15); }
.perm-matrix td.is-focus { background: rgba(184, 240, 0, 0.12); }

.perm-legend {
  margin-top: 0.85rem;
  font-size: 0.8rem;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.perm-dot {
  display: inline-block;
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 50%;
  vertical-align: middle;
}

.perm-dot.on {
  background: var(--accent);
  box-shadow: 0 0 0 1px rgba(26, 46, 0, 0.15);
}

.perm-dot.off { border: 1px solid var(--line); }

.authz-stack {
  list-style: none;
  display: grid;
  gap: 0.65rem;
}

.authz-stack li {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 1rem;
  align-items: start;
  padding: 1.1rem 1.25rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 3px solid var(--forest);
  animation: rise 0.5s ease-out both;
}

.authz-stack li:nth-child(2) { animation-delay: 0.05s; border-left-color: #3d8f7a; }
.authz-stack li:nth-child(3) { animation-delay: 0.1s; border-left-color: #6bb89a; }
.authz-stack li:nth-child(4) { animation-delay: 0.15s; border-left-color: var(--accent); }

.authz-stack .n {
  font-family: "Bricolage Grotesque", sans-serif;
  font-weight: 800;
  font-size: 1.4rem;
  color: var(--forest);
  line-height: 1;
  min-width: 1.5rem;
}

.authz-stack h3 {
  font-family: "Bricolage Grotesque", sans-serif;
  font-size: 1.05rem;
  letter-spacing: -0.02em;
  margin-bottom: 0.2rem;
}

.authz-stack p { color: var(--ink-soft); font-size: 0.92rem; }

.notes-list {
  list-style: none;
  display: grid;
  gap: 0.55rem;
}

.notes-list li {
  padding: 0.85rem 1rem;
  background: var(--surface);
  border: 1px solid var(--line);
  font-size: 0.92rem;
  color: var(--ink-soft);
  border-left: 3px solid var(--line);
}

.notes-list li::before {
  content: "→ ";
  color: var(--forest);
  font-family: "IBM Plex Mono", monospace;
}

@media (max-width: 960px) {
  .hero-roles { grid-template-columns: 1fr; }
  .roles-ladder { justify-self: start; max-width: 360px; order: -1; }
  .role-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 720px) {
  .nav-center { gap: 0.75rem; }
  .nav-links { display: none; }
  .site-tabs { margin-left: auto; }
}

@media (max-width: 560px) {
  .lane-grid,
  .role-grid { grid-template-columns: 1fr; }
  .hero-roles { min-height: auto; }
}

/* Capability Orbit — scoped under #view-orbit */
#view-orbit {
  --space: #0b0e16;
  --space-2: #0d1120;
  --surface: #10141f;
  --ink: #e9edf6;
  --ink-soft: #b4bdd1;
  --muted: #7d879f;
  --line: rgba(148, 163, 199, 0.14);
  --line-strong: rgba(148, 163, 199, 0.28);
  --accent: #e3c284;
  --accent-bright: #f0d9a8;
  --accent-ink: #1c1508;
  --gym: #5fb8a6;
  --gym-soft: rgba(95, 184, 166, 0.12);
  --client: #7fa8d9;
  --client-soft: rgba(127, 168, 217, 0.12);
  --platform: #a390cf;
  --platform-soft: rgba(163, 144, 207, 0.14);
  --radius: 2px;
  --max: 1120px;
  --dock-w: 320px;

  color: var(--ink);
  background: var(--space);
  font-family: "IBM Plex Sans", sans-serif;
  position: relative;
  min-height: calc(100vh - var(--nav-h, 64px));
}

#view-orbit::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    radial-gradient(ellipse 65% 45% at 72% -5%, rgba(96, 118, 176, 0.14) 0%, transparent 62%),
    radial-gradient(ellipse 50% 40% at 12% 55%, rgba(227, 194, 132, 0.05) 0%, transparent 58%);
}

#view-orbit > * { position: relative; z-index: 1; }

#view-orbit a { color: var(--accent); text-decoration-thickness: 1px; text-underline-offset: 3px; }
#view-orbit a:hover { color: var(--accent-bright); }
#view-orbit :focus-visible {
  outline: 1px solid var(--accent);
  outline-offset: 3px;
}

#view-orbit .wrap {
  width: min(100% - 2.5rem, var(--max));
  margin-inline: auto;
}

#view-orbit .eyebrow, #view-orbit .sec-label{
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 500;
}#view-orbit /* —— Hero —— */
.hero{
  position: relative;
  min-height: min(88vh, 720px);
  display: flex;
  align-items: flex-end;
  padding: 4rem 0 3.5rem;
  overflow: hidden;
}#view-orbit .hero-atmosphere{
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 64% 38%, rgba(227, 194, 132, 0.09) 0%, transparent 30%),
    radial-gradient(circle at 58% 46%, rgba(107, 134, 196, 0.1) 0%, transparent 45%);
  animation: core-breathe 9s ease-in-out infinite;
}@keyframes core-breathe{
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.05); opacity: 0.8; }
}#view-orbit .hero-inner{
  position: relative;
  max-width: 36rem;
  padding-bottom: 0.5rem;
}#view-orbit .hero h1{
  font-family: "Space Grotesk", sans-serif;
  font-weight: 700;
  font-size: clamp(3.25rem, 9vw, 5.5rem);
  line-height: 0.95;
  letter-spacing: -0.03em;
  color: var(--ink);
  margin: 0.6rem 0 1rem;
}#view-orbit .lede{
  font-size: 1.125rem;
  color: var(--ink-soft);
  max-width: 28rem;
  margin-bottom: 1.75rem;
}#view-orbit .cta-row{
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
  align-items: center;
}#view-orbit .cta{
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.85rem 1.25rem;
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 600;
  text-decoration: none;
