import { ROADMAP } from './roadmap-data.js';


const CX = 320;
const CY = 320;
const RADII = { 1: 145, 2: 210, 3: 275 };
const OWN_STROKE = {
  gym: "#5fb8a6",
  client: "#7fa8d9",
  platform: "#a390cf",
  done: "#e3c284",
};
const OWN_FILL = {
  gym: "#122b28",
  client: "#14213a",
  platform: "#211d38",
  done: "#e3c284",
};

/** @type {Map<string, object>} */
const itemIndex = new Map();

function indexData() {
  for (const item of ROADMAP.foundation.items) {
    itemIndex.set(item.id, { item, stint: ROADMAP.foundation, kind: "foundation" });
  }
  if (ROADMAP.pullForward) {
    for (const item of ROADMAP.pullForward.items) {
      itemIndex.set(item.id, { item, stint: ROADMAP.pullForward, kind: "pull-forward" });
    }
  }
  for (const stint of ROADMAP.stints) {
    for (const item of stint.items) {
      itemIndex.set(item.id, { item, stint, kind: "stint" });
    }
  }
}

function svgEl(name, attrs = {}) {
  const el = document.createElementNS("http://www.w3.org/2000/svg", name);
  for (const [k, v] of Object.entries(attrs)) {
    el.setAttribute(k, String(v));
  }
  return el;
}

function polar(angleDeg, r) {
  const rad = ((angleDeg - 90) * Math.PI) / 180;
  return { x: CX + r * Math.cos(rad), y: CY + r * Math.sin(rad) };
}

function progressFraction(items) {
  if (!items.length) return 0;
  const done = items.filter((i) => i.status === "done").length;
  return done / items.length;
}

function describeArc(r, fraction) {
  if (fraction <= 0) return "";
  if (fraction >= 1) {
    return `M ${CX} ${CY - r} A ${r} ${r} 0 1 1 ${CX - 0.01} ${CY - r}`;
  }
  const end = polar(fraction * 360, r);
  const large = fraction > 0.5 ? 1 : 0;
  return `M ${CX} ${CY - r} A ${r} ${r} 0 ${large} 1 ${end.x} ${end.y}`;
}

function renderOrbit() {
  const rings = document.getElementById("orbit-rings");
  const progress = document.getElementById("orbit-progress");
  const core = document.getElementById("orbit-core");
  const nodes = document.getElementById("orbit-nodes");
  const spokes = document.getElementById("orbit-spokes");

  rings.replaceChildren();
  progress.replaceChildren();
  core.replaceChildren();
  nodes.replaceChildren();
  spokes.replaceChildren();

  for (const stint of ROADMAP.stints) {
    const r = RADII[stint.orbit];
    rings.appendChild(
      svgEl("circle", {
        cx: CX,
        cy: CY,
        r,
        fill: "none",
        stroke: "#39435f",
        "stroke-width": 1.25,
        class: "orbit-ring-path",
        opacity: 0.95,
      }),
    );

    const frac = progressFraction(stint.items);
    if (frac > 0) {
      const arc = svgEl("path", {
        d: describeArc(r, frac),
        fill: "none",
        stroke: "#e3c284",
        "stroke-width": 4,
        "stroke-linecap": "round",
        class: "progress-arc",
        "data-orbit": stint.orbit,
      });
      progress.appendChild(arc);
    }

    const labelPos = polar(215 + stint.orbit * 8, r);
    const label = svgEl("text", {
      x: labelPos.x,
      y: labelPos.y,
      fill: "#6f7994",
      "font-family": "IBM Plex Mono, monospace",
      "font-size": 10,
      "text-anchor": "middle",
      class: "orbit-label",
    });
    label.textContent = `ORBIT ${stint.orbit}`;
    rings.appendChild(label);
  }

  // Core
  core.appendChild(
    svgEl("circle", {
      cx: CX,
      cy: CY,
      r: 72,
      fill: "#e3c284",
      opacity: 0.06,
    }),
  );
  core.appendChild(
    svgEl("circle", {
      cx: CX,
      cy: CY,
      r: 54,
      fill: "#e3c284",
      stroke: "#f0d9a8",
      "stroke-width": 1.5,
      filter: "url(#soft-glow)",
      class: "core-disk",
      style: "cursor:pointer",
      id: "core-hit",
      tabindex: "0",
      role: "button",
      "aria-label": "Foundation — Auth and Gym Org shipped",
    }),
  );
  const coreTitle = svgEl("text", {
    x: CX,
    y: CY - 6,
    fill: "#1c1508",
    "font-family": "Space Grotesk, sans-serif",
    "font-size": 13,
    "font-weight": 700,
    "text-anchor": "middle",
  });
  coreTitle.textContent = "FOUNDATION";
  core.appendChild(coreTitle);
  const coreSub = svgEl("text", {
    x: CX,
    y: CY + 12,
    fill: "#1c1508",
    "font-family": "IBM Plex Mono, monospace",
    "font-size": 9,
    "text-anchor": "middle",
    opacity: 0.75,
  });
  coreSub.textContent = "AUTH · GYM-ORGS";
  core.appendChild(coreSub);

  document.getElementById("core-hit").addEventListener("click", () => selectFoundation());
  document.getElementById("core-hit").addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      selectFoundation();
    }
  });

  for (const stint of ROADMAP.stints) {
    const r = RADII[stint.orbit];
    const n = stint.items.length;
    const startAngle = stint.orbit === 1 ? -20 : stint.orbit === 2 ? 10 : -5;
    const sweep = 300;
    stint.items.forEach((item, i) => {
      const angle = startAngle + (sweep / Math.max(n - 1, 1)) * i;
      const { x, y } = polar(angle, r);
      const g = svgEl("g", {
        class: "orbit-node",
        tabindex: "0",
        role: "button",
        "aria-label": `${item.num} ${item.title}`,
        "data-id": item.id,
        transform: `translate(${x} ${y})`,
      });

      const pulse = svgEl("g", { class: "node-pulse" });
      const own = item.status === "done" ? "done" : item.ownership;
      const disk = svgEl("circle", {
        class: "node-disk",
        cx: 0,
        cy: 0,
        r: 11,
        fill: OWN_FILL[own],
        stroke: OWN_STROKE[own],
        "stroke-width": own === "client" ? 2 : 2.25,
        "stroke-dasharray": own === "client" ? "3 2" : "none",
      });
      pulse.appendChild(disk);

      const label = svgEl("text", {
        x: 0,
        y: 3.5,
        fill: own === "done" ? "#1c1508" : OWN_STROKE[own],
        "font-family": "IBM Plex Mono, monospace",
        "font-size": 8,
        "font-weight": 500,
        "text-anchor": "middle",
        "pointer-events": "none",
      });
      label.textContent = item.num;
      pulse.appendChild(label);
      g.appendChild(pulse);

      g.addEventListener("click", (e) => {
        e.stopPropagation();
        selectItem(item.id);
      });
      g.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          selectItem(item.id);
        }
      });

      nodes.appendChild(g);
    });
  }
}

/** @type {{ title: string, detail: object, exit?: string | null } | null} */
let dockDetailPayload = null;

function setDock({ kicker, title, body, meta, exit, ownership, detail }) {
  const dock = document.getElementById("dock");
  dock.dataset.ownership = ownership || "gym";
  document.getElementById("dock-kicker").textContent = kicker;
  document.getElementById("dock-title").textContent = title;
  document.getElementById("dock-body").textContent = body;

  const metaEl = document.getElementById("dock-meta");
  const exitEl = document.getElementById("dock-exit");
  const detailBtn = document.getElementById("dock-detail-btn");

  if (meta && Object.keys(meta).length) {
    metaEl.hidden = false;
    metaEl.replaceChildren();
    for (const [k, v] of Object.entries(meta)) {
      const row = document.createElement("div");
      const dt = document.createElement("dt");
      dt.textContent = k;
      const dd = document.createElement("dd");
      dd.textContent = v;
      row.append(dt, dd);
      metaEl.appendChild(row);
    }
  } else {
    metaEl.hidden = true;
    metaEl.replaceChildren();
  }

  if (exit) {
    exitEl.hidden = false;
    exitEl.textContent = `Exit: ${exit}`;
  } else {
    exitEl.hidden = true;
    exitEl.textContent = "";
  }

  if (detail && typeof window.openReaderModal === "function") {
    dockDetailPayload = { title, detail, exit: exit || null };
    if (detailBtn) detailBtn.hidden = false;
  } else {
    dockDetailPayload = null;
    if (detailBtn) detailBtn.hidden = true;
  }
}

function openDockDetail() {
  if (!dockDetailPayload || typeof window.openReaderModal !== "function") return;
  const { title, detail, exit } = dockDetailPayload;
  window.openReaderModal({
    title,
    kicker: "Orbit · detailed view",
    showToc: true,
    sections: window.sectionsFromDetail(detail, { exit }),
  });
}

function clearNodeSelection() {
  document.querySelectorAll(".orbit-node.is-selected").forEach((n) => n.classList.remove("is-selected"));
  document.querySelectorAll(".item-list li.is-active").forEach((n) => n.classList.remove("is-active"));
}

function selectFoundation() {
  clearNodeSelection();
  setDock({
    kicker: "Foundation · shipped",
    title: ROADMAP.foundation.title,
    body: ROADMAP.foundation.body,
    meta: {
      Modules: "M1 Identity · M2 Gym Org",
      Paths: "src/features/auth · src/features/gym-orgs",
      Status: "Done",
    },
    exit: null,
    ownership: "done",
    detail: ROADMAP.foundation.detail || null,
  });
  pauseOrbitBriefly();
}

function selectItem(id) {
  const entry = itemIndex.get(id);
  if (!entry) return;
  const { item, stint, kind } = entry;

  clearNodeSelection();
  document.querySelectorAll(`.orbit-node[data-id="${id}"]`).forEach((n) => n.classList.add("is-selected"));
  document.querySelectorAll(`.item-list li[data-id="${id}"]`).forEach((n) => n.classList.add("is-active"));

  const meta = {
    PRD: item.prd,
    Paths: item.paths,
    Ownership: ownershipLabel(item.ownership),
    Status: item.status === "done" ? "Shipped" : "Todo",
  };

  setDock({
    kicker: kind === "foundation" ? "Foundation" : `${stint.label} · ${stint.title}`,
    title: `${item.num}  ${item.title}`,
    body: item.body,
    meta,
    exit: kind === "stint" || kind === "pull-forward" ? stint.exit : null,
    ownership: item.status === "done" ? "done" : item.ownership,
    detail: item.detail || null,
  });

  pauseOrbitBriefly();
}

function ownershipLabel(o) {
  if (o === "gym") return "Gym-owned";
  if (o === "client") return "Client-owned";
  if (o === "platform") return "Platform";
  if (o === "done") return "Shipped";
  return o;
}

function ownershipClass(o) {
  return `own-${o === "done" ? "done" : o}`;
}

let pauseTimer = null;
function pauseOrbitBriefly() {
  const frame = document.getElementById("orbit-frame");
  frame.classList.add("is-paused");
  clearTimeout(pauseTimer);
  pauseTimer = setTimeout(() => frame.classList.remove("is-paused"), 4500);
}

function renderRunsheet() {
  const root = document.getElementById("runsheet-root");
  root.replaceChildren();

  // Foundation
  const fBlock = document.createElement("article");
  fBlock.className = "stint-block foundation-block";
  fBlock.innerHTML = `
    <div class="stint-head">
      <h3>Foundation</h3>
      <span class="stint-tag">Shipped</span>
    </div>
    <p class="stint-outcome">${escapeHtml(ROADMAP.foundation.body)}</p>
  `;
  const fList = document.createElement("ul");
  fList.className = "item-list";
  for (const item of ROADMAP.foundation.items) {
    fList.appendChild(runsheetItem(item, false));
  }
  fBlock.appendChild(fList);
  root.appendChild(fBlock);

  if (ROADMAP.pullForward) {
    const pf = ROADMAP.pullForward;
    const pfBlock = document.createElement("article");
    pfBlock.className = "stint-block pull-forward-block";
    pfBlock.id = "stint-pull-forward";
    pfBlock.innerHTML = `
      <div class="stint-head">
        <h3>${escapeHtml(pf.label)} — ${escapeHtml(pf.title)}</h3>
        <span class="stint-tag">${escapeHtml(pf.tagline)}</span>
      </div>
      <p class="stint-outcome">${escapeHtml(pf.outcome)}</p>
    `;
    const pfList = document.createElement("ul");
    pfList.className = "item-list";
    for (const item of pf.items) {
      pfList.appendChild(runsheetItem(item, true));
    }
    pfBlock.appendChild(pfList);
    const pfExit = document.createElement("p");
    pfExit.className = "exit-banner";
    pfExit.textContent = `Exit: ${pf.exit}`;
    pfBlock.appendChild(pfExit);
    root.appendChild(pfBlock);
  }

  for (const stint of ROADMAP.stints) {
    const block = document.createElement("article");
    block.className = "stint-block";
    block.id = `stint-${stint.orbit}`;
    block.innerHTML = `
      <div class="stint-head">
        <h3>${escapeHtml(stint.label)} — ${escapeHtml(stint.title)}</h3>
        <span class="stint-tag">${escapeHtml(stint.tagline)}</span>
      </div>
      <p class="stint-outcome">${escapeHtml(stint.outcome)}</p>
    `;
    const list = document.createElement("ul");
    list.className = "item-list";
    for (const item of stint.items) {
      list.appendChild(runsheetItem(item, true));
    }
    block.appendChild(list);

    const exit = document.createElement("p");
    exit.className = "exit-banner";
    exit.textContent = `Exit: ${stint.exit}`;
    block.appendChild(exit);

    root.appendChild(block);
  }
}

function runsheetItem(item, clickable) {
  const li = document.createElement("li");
  li.dataset.id = item.id;
  if (item.status === "done") li.classList.add("is-done");
  const ownLabel =
    item.status === "done"
      ? item.ownership === "done"
        ? "Shipped"
        : `Shipped · ${ownershipLabel(item.ownership)}`
      : ownershipLabel(item.ownership);
  const ownClass = item.status === "done" ? "own-done" : ownershipClass(item.ownership);
  li.innerHTML = `
    <span class="num">${escapeHtml(item.num)}</span>
    <span>
      <span class="title">${escapeHtml(item.title)}</span>
      <span class="paths">${escapeHtml(item.paths)}</span>
    </span>
    <span class="own ${ownClass}">${escapeHtml(ownLabel)}</span>
  `;
  if (clickable) {
    li.addEventListener("click", () => {
      selectItem(item.id);
      document.getElementById("orbit").scrollIntoView({ behavior: "smooth", block: "start" });
    });
  }
  return li;
}

function renderDeferred() {
  const ul = document.getElementById("deferred-list");
  ul.replaceChildren();
  for (const d of ROADMAP.deferred) {
    const li = document.createElement("li");
    li.textContent = d;
    ul.appendChild(li);
  }
}

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

let orbitBooted = false;

export function bootOrbit() {
  if (orbitBooted) return;
  if (!document.getElementById("orbit-svg")) return;

  indexData();
  renderOrbit();
  renderRunsheet();
  renderDeferred();
  selectFoundation();

  const frame = document.getElementById("orbit-frame");
  frame.addEventListener("mouseenter", () => frame.classList.add("is-paused"));
  frame.addEventListener("mouseleave", () => frame.classList.remove("is-paused"));

  document.getElementById("dock-detail-btn")?.addEventListener("click", openDockDetail);

  orbitBooted = true;
}

window.bootOrbit = bootOrbit;

:root {
  --space: #0b0e16;
  --ink: #e9edf6;
  --ink-soft: #b4bdd1;
  --muted: #7d879f;
  --line: rgba(148, 163, 199, 0.18);
  --surface: rgba(16, 20, 33, 0.78);
  --accent: #e3c284;
  --accent-bright: #f0d9a8;
  --accent-ink: #1c1508;
  --gym: #5fb8a6;
  --gym-soft: rgba(95, 184, 166, 0.14);
  --client: #7fa8d9;
  --client-soft: rgba(127, 168, 217, 0.14);
  --platform: #a390cf;
  --platform-soft: rgba(163, 144, 207, 0.16);
  --radius: 2px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  height: 100%;
  overflow: hidden;
}

body {
  font-family: "IBM Plex Sans", sans-serif;
  color: var(--ink);
  background: var(--space);
}

#viewport {
  position: fixed;
  inset: 0;
}

#viewport canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
}

/* Soft vignette — deepens the field edges without crushing blacks */
body::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    radial-gradient(ellipse 70% 60% at 50% 45%, transparent 42%, rgba(4, 6, 12, 0.5) 100%),
    linear-gradient(180deg, rgba(11, 14, 22, 0.4) 0%, transparent 16%, transparent 76%, rgba(11, 14, 22, 0.5) 100%);
}

.chrome {
  position: fixed;
  z-index: 2;
  pointer-events: none;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 700ms ease, transform 700ms ease;
}

body.ready .chrome {
  opacity: 1;
  transform: none;
}

.chrome a,
.chrome .dock,
.nav {
  pointer-events: auto;
}

.brand {
  top: clamp(1.25rem, 3vw, 2rem);
  left: clamp(1.25rem, 3vw, 2rem);
  max-width: min(22rem, calc(100vw - 12rem));
}

.eyebrow {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 500;
}

.brand h1 {
  font-family: "Space Grotesk", sans-serif;
  font-weight: 700;
  font-size: clamp(2.4rem, 5.5vw, 3.5rem);
  line-height: 0.92;
  letter-spacing: -0.035em;
  margin: 0.4rem 0 0.55rem;
}

.lede {
  font-size: 0.95rem;
  color: var(--ink-soft);
  max-width: 17rem;
  line-height: 1.45;
}

.nav {
  top: clamp(1.25rem, 3vw, 2rem);
  right: clamp(1.25rem, 3vw, 2rem);
  display: flex;
  gap: 0.1rem;
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: var(--surface);
  border: 1px solid var(--line);
  padding: 0.18rem;
  backdrop-filter: blur(12px) saturate(1.1);
  transition-delay: 80ms;
}

.nav a,
.nav span {
  padding: 0.42rem 0.75rem;
  text-decoration: none;
  color: var(--muted);
}

.nav a:hover { color: var(--ink); }

.nav [aria-current="page"] {
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 500;
}

.legend {
  top: 5.1rem;
  right: clamp(1.25rem, 3vw, 2rem);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.4rem;
  font-size: 0.72rem;
  letter-spacing: 0.02em;
  color: var(--muted);
  transition-delay: 120ms;
}

.lg {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.2rem 0.45rem 0.2rem 0.35rem;
  background: rgba(16, 20, 33, 0.6);
  border: 1px solid transparent;
  backdrop-filter: blur(8px);
}

.lg i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: 1.5px solid currentColor;
  display: block;
}

.lg.gym { color: var(--gym); }
.lg.gym i { background: var(--gym-soft); }
.lg.client { color: var(--client); }
.lg.client i { background: var(--client-soft); border-style: dashed; }
.lg.platform { color: var(--platform); }
.lg.platform i { background: var(--platform-soft); }
.lg.done { color: var(--accent); }
.lg.done i { background: var(--accent); border-color: var(--accent-bright); }

.dock {
  bottom: clamp(1.25rem, 3vw, 2rem);
  right: clamp(1.25rem, 3vw, 2rem);
  width: min(21rem, calc(100vw - 3rem));
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 3px solid var(--gym);
  padding: 1.2rem 1.25rem 1.25rem;
  backdrop-filter: blur(16px) saturate(1.15);
  max-height: min(44vh, 380px);
  overflow: auto;
  transition-delay: 160ms;
}

.dock.dock-in {
  animation: dock-settle 420ms cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes dock-settle {
  from {
    opacity: 0.55;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.dock[data-ownership="client"] { border-left-color: var(--client); }
.dock[data-ownership="platform"] { border-left-color: var(--platform); }
.dock[data-ownership="gym"] { border-left-color: var(--gym); }
.dock[data-ownership="done"] { border-left-color: var(--accent); }

.dock-kicker {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.62rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 0.35rem;
}

.dock-title {
  font-family: "Space Grotesk", sans-serif;
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.12;
  margin-bottom: 0.55rem;
}

.dock-body {
  font-size: 0.9rem;
  color: var(--ink-soft);
  margin-bottom: 0.95rem;
  line-height: 1.5;
}

.dock-meta {
  display: grid;
  gap: 0.5rem;
  margin-bottom: 0.85rem;
  font-size: 0.8rem;
  padding-top: 0.75rem;
  border-top: 1px solid var(--line);
}

.dock-meta div {
  display: grid;
  grid-template-columns: 4.75rem 1fr;
  gap: 0.4rem;
}

.dock-meta dt {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.62rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  padding-top: 0.12rem;
}

.dock-meta dd {
  color: var(--ink);
  word-break: break-word;
}

.dock-exit {
  font-size: 0.8rem;
  color: var(--accent);
  background: rgba(227, 194, 132, 0.08);
  border: 1px solid rgba(227, 194, 132, 0.18);
  padding: 0.6rem 0.7rem;
  line-height: 1.4;
}

.dock-detail-btn {
  margin-top: 0.85rem;
  appearance: none;
  width: 100%;
  border: 1px solid rgba(227, 194, 132, 0.45);
  background: rgba(227, 194, 132, 0.12);
  color: var(--accent);
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 0.65rem 0.75rem;
  cursor: pointer;
  text-align: left;
}

.dock-detail-btn:hover {
  background: rgba(227, 194, 132, 0.22);
}

.dock-detail-btn[hidden] {
  display: none !important;
}

.hint {
  bottom: clamp(1.25rem, 3vw, 2rem);
  left: clamp(1.25rem, 3vw, 2rem);
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.68rem;
  color: var(--muted);
  letter-spacing: 0.04em;
  transition-delay: 200ms;
}

.label3d {
  font-family: "IBM Plex Mono", monospace;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--ink);
  background: rgba(13, 17, 28, 0.85);
  border: 1px solid var(--line);
  padding: 3px 6px;
  white-space: nowrap;
  user-select: none;
  pointer-events: none;
  transform: translate(-50%, -145%);
  backdrop-filter: blur(6px);
}

.label3d.is-selected {
  background: var(--accent);
  border-color: var(--accent-bright);
  color: var(--accent-ink);
}

.label-core {
  font-size: 11px;
  letter-spacing: 0.14em;
  padding: 4px 8px;
}

.label-orbit {
  font-size: 9px;
  letter-spacing: 0.12em;
  color: var(--muted);
  background: rgba(11, 14, 22, 0.6);
  border-color: transparent;
  transform: translate(-50%, 40%);
}

@media (max-width: 720px) {
  .legend { display: none; }

  .dock {
    left: 1rem;
    right: 1rem;
    width: auto;
    bottom: 1rem;
    max-height: 34vh;
  }

  .hint { display: none; }

  .brand {
    max-width: calc(100vw - 7rem);
  }

  .brand h1 {
    font-size: 1.85rem;
  }

  .lede { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .chrome {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .dock.dock-in {
    animation: none;
  }
}

(() => {
  /* ── Product modules ─────────────────────────────────────────── */
  const modules = window.MODULES_DATA || [];

  const grid = document.getElementById("mod-grid");

  function openModuleDetail(m) {
    if (!m?.detail || typeof window.openReaderModal !== "function") return;
    window.openReaderModal({
      title: `${m.id}  ${m.name}`,
      kicker: "Module · how it works",
      showToc: true,
      sections: window.sectionsFromDetail(m.detail),
    });
  }

  function renderModules(filter = "all") {
    grid.innerHTML = "";
    modules.forEach((m) => {
      if (filter !== "all" && !m.filters.includes(filter)) return;
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "mod";
      btn.dataset.id = m.id;
      const how = (m.howItWorks || [])
        .map((step) => `<li>${step}</li>`)
        .join("");
      btn.innerHTML = `
        <div class="mod-head">
          <div>
            <div class="mod-id">${m.id}</div>
            <div class="mod-name">${m.name}</div>
            <div class="mod-tags">
              ${m.tags.map((t) => `<span class="tag ${t}">${t}</span>`).join("")}
            </div>
          </div>
          <div class="chev" aria-hidden="true">+</div>
        </div>
        <div class="mod-body">
          ${m.summary ? `<p class="mod-summary">${m.summary}</p>` : ""}
          ${m.personas ? `<p class="mod-personas"><strong>Who:</strong> ${m.personas}</p>` : ""}
          ${how ? `<p class="mod-how-label">How it works</p><ol class="mod-how">${how}</ol>` : ""}
          <ul>
            ${m.items
              .map((item) => {
                if (typeof item === "string") return `<li>${item}</li>`;
                return `<li class="out">${item.text}</li>`;
              })
              .join("")}
          </ul>
          ${
            m.detail
              ? `<div class="mod-actions"><span class="cta cta-ghost mod-detail-btn" data-mod="${m.id}" role="button" tabindex="0">How it works — full detail</span></div>`
              : ""
          }
        </div>
      `;
      btn.addEventListener("click", (e) => {
        if (e.target.closest(".mod-detail-btn")) {
          e.preventDefault();
          e.stopPropagation();
          openModuleDetail(m);
          return;
        }
        const wasOpen = btn.classList.contains("open");
        grid.querySelectorAll(".mod.open").forEach((el) => el.classList.remove("open"));
        if (!wasOpen) btn.classList.add("open");
      });
      grid.appendChild(btn);
    });
  }

  renderModules();

  document.querySelectorAll(".mod-toolbar .filter-btn").forEach((b) => {
    b.addEventListener("click", () => {
      document.querySelectorAll(".mod-toolbar .filter-btn").forEach((x) => x.classList.remove("active"));
      b.classList.add("active");
      renderModules(b.dataset.filter);
    });
  });

  document.getElementById("open-full-prd")?.addEventListener("click", () => {
    const prd = window.PRD_READER;
    if (!prd || typeof window.openReaderModal !== "function") return;
    window.openReaderModal({
      title: prd.title,
      kicker: prd.kicker,
      showToc: true,
      sections: prd.sections,
    });
  });

  /* ── Roles & permissions ─────────────────────────────────────── */
  const ROLE_ORDER = ["CLIENT", "STAFF_UNASSIGNED", "TRAINER", "ADMIN"];
  const CHECK =
    '<svg viewBox="0 0 12 12" fill="none" aria-hidden="true"><path d="M2.5 6.2l2.4 2.4 4.6-5" stroke="currentColor" stroke-width="1.6" stroke-linecap="square"/></svg>';
  const { roles, permissions, authzLayers, notes } = window.ROLES_DATA;
  let activeRole = "ALL";
  let rolesBooted = false;

  function countFor(code) {
    return permissions.filter((p) => p.roles.includes(code)).length;
  }

  function renderRoles() {
    const roleGrid = document.getElementById("role-grid");
    roleGrid.innerHTML = roles
      .map(
        (r) => `
      <button type="button" class="role-card${activeRole === r.code ? " is-active" : ""}" data-role="${r.code}" data-color="${r.color}" role="option" aria-selected="${activeRole === r.code}">
        <p class="code">${r.code}</p>
        <span class="lane-pill">${r.lane}</span>
        <h3>${r.name}</h3>
        <p class="count">${countFor(r.code)} permissions</p>
      </button>`
      )
      .join("");

    roleGrid.querySelectorAll(".role-card").forEach((btn) => {
      btn.addEventListener("click", () => {
        const code = btn.dataset.role;
        activeRole = activeRole === code ? "ALL" : code;
        syncRoles();
      });
    });

    const detail = document.getElementById("role-detail");
    const selected = roles.find((r) => r.code === activeRole);
    detail.textContent = selected
      ? selected.blurb
      : "Showing the full matrix. Select a role to highlight its grants.";
  }

  function renderPermFilters() {
    const root = document.getElementById("matrix-filters");
    const items = [
      { code: "ALL", label: "All" },
      ...roles.map((r) => ({
        code: r.code,
        label: r.code === "STAFF_UNASSIGNED" ? "Unassigned" : r.name,
      })),
    ];
    root.innerHTML = items
      .map(
        (i) =>
          `<button type="button" class="perm-filter${activeRole === i.code ? " is-active" : ""}" data-role="${i.code}">${i.label}</button>`
      )
      .join("");

    root.querySelectorAll(".perm-filter").forEach((btn) => {
      btn.addEventListener("click", () => {
        activeRole = btn.dataset.role;
        syncRoles();
      });
    });
  }

  function renderPermMatrix() {
    const body = document.getElementById("matrix-body");
    const groups = [...new Set(permissions.map((p) => p.group))];
    let html = "";

    for (const group of groups) {
      html += `<tr class="group-row"><td colspan="5">${group}</td></tr>`;
      for (const perm of permissions.filter((p) => p.group === group)) {
        const holds = activeRole === "ALL" || perm.roles.includes(activeRole);
        const rowClass = activeRole === "ALL" ? "" : holds ? "is-highlight" : "is-dimmed";
        const cells = ROLE_ORDER.map((role) => {
          const on = perm.roles.includes(role);
          const focus = activeRole !== "ALL" && activeRole === role && on;
          return `<td class="${focus ? "is-focus" : ""}"><span class="cell ${on ? "on" : "off"}" title="${on ? "granted" : "not granted"}">${on ? CHECK : ""}</span></td>`;
        }).join("");
        html += `<tr class="${rowClass}">
          <td>
            <span class="perm-code">${perm.code}</span>
            <span class="perm-label">${perm.label}</span>
          </td>
          ${cells}
        </tr>`;
      }
    }

    body.innerHTML = html;
  }

  function renderAuthzStack() {
    document.getElementById("authz-stack").innerHTML = authzLayers
      .map(
        (layer, i) => `
      <li>
        <span class="n" aria-hidden="true">${String(i + 1).padStart(2, "0")}</span>
        <div>
          <h3>${layer.title}</h3>
          <p>${layer.body}</p>
        </div>
      </li>`
      )
      .join("");
  }

  function renderNotes() {
    document.getElementById("notes-list").innerHTML = notes.map((n) => `<li>${n}</li>`).join("");
  }

  function syncRoles() {
    renderRoles();
    renderPermFilters();
    renderPermMatrix();
  }

  function bootRoles() {
    if (rolesBooted) {
      syncRoles();
      return;
    }
    syncRoles();
    renderAuthzStack();
    renderNotes();
    rolesBooted = true;
  }

  /* ── Tabs ────────────────────────────────────────────────────── */
  const viewPrd = document.getElementById("view-prd");
  const viewRoles = document.getElementById("view-roles");
  const viewOrbit = document.getElementById("view-orbit");
  const navPrd = document.getElementById("nav-links-prd");
  const navRoles = document.getElementById("nav-links-roles");
  const navOrbit = document.getElementById("nav-links-orbit");
  const tabBtns = [...document.querySelectorAll(".site-tab")];
  const views = { prd: viewPrd, roles: viewRoles, orbit: viewOrbit };
  const navs = { prd: navPrd, roles: navRoles, orbit: navOrbit };
  const titles = {
    prd: "Gym SaaS — Product Blueprint",
    roles: "Gym SaaS — Roles & Permissions",
    orbit: "Gym SaaS — Capability Orbit",
  };

  function setTab(tab, { pushHash = true } = {}) {
    if (!views[tab]) tab = "prd";

    tabBtns.forEach((btn) => {
      const on = btn.dataset.tab === tab;
      btn.classList.toggle("is-active", on);
      btn.setAttribute("aria-selected", String(on));
    });

    for (const [key, el] of Object.entries(views)) {
      const on = key === tab;
      el.classList.toggle("is-active", on);
      el.hidden = !on;
    }

    for (const [key, el] of Object.entries(navs)) {
      const on = key === tab;
      el.hidden = !on;
      el.classList.toggle("is-hidden", !on);
    }

    document.title = titles[tab] ?? titles.prd;

    if (tab === "roles") bootRoles();
    if (tab === "orbit") {
      if (typeof window.bootOrbit === "function") window.bootOrbit();
      else {
        // orbit-app.js is a deferred module — retry briefly
        let n = 0;
        const t = setInterval(() => {
          n += 1;
          if (typeof window.bootOrbit === "function") {
            window.bootOrbit();
            clearInterval(t);
          } else if (n > 40) clearInterval(t);
        }, 50);
      }
    }

    if (pushHash) {
      const sectionHashes =
        /^(positioning|surfaces|modules|matrix|stack|out|lanes|roles-pick|perm-matrix|authz|roles-notes|roles-top|orbit|orbit-top|runsheet|deferred)$/;
      const next = `#${tab}`;
      if (location.hash !== next && !sectionHashes.test(location.hash.slice(1))) {
        history.replaceState(null, "", next);
      }
    }

    window.scrollTo({ top: 0, behavior: "instant" in window ? "instant" : "auto" });
  }

  tabBtns.forEach((btn) => {
    btn.addEventListener("click", () => {
      setTab(btn.dataset.tab);
      history.replaceState(null, "", `#${btn.dataset.tab}`);
    });
  });

  document.querySelectorAll("[data-goto-tab]").forEach((el) => {
    el.addEventListener("click", () => {
      const tab = el.getAttribute("data-goto-tab");
      setTab(tab);
      history.replaceState(null, "", `#${tab}`);
    });
  });

  document.querySelectorAll('[data-tab-home="prd"]').forEach((el) => {
    el.addEventListener("click", (e) => {
      if (viewPrd.hidden) {
        e.preventDefault();
        setTab("prd");
        history.replaceState(null, "", "#prd");
      }
    });
  });

  function tabFromHash() {
    const h = location.hash.slice(1);
    if (
      h === "roles" ||
      ["lanes", "roles-pick", "perm-matrix", "authz", "roles-notes", "roles-top"].includes(h)
    ) {
      return "roles";
    }
    if (
      h === "orbit" ||
      ["orbit-top", "runsheet", "deferred"].includes(h) ||
      h === "orbit" /* keep */
    ) {
      // #orbit is both tab id and section — treat as orbit tab
      if (h === "orbit" || ["orbit-top", "runsheet", "deferred"].includes(h)) return "orbit";
    }
    if (h === "prd" || h === "top" || h === "") return "prd";
    // Product section anchors
    if (["positioning", "surfaces", "modules", "matrix", "stack", "out"].includes(h)) return "prd";
    return "prd";
  }

  setTab(tabFromHash(), { pushHash: false });

  window.addEventListener("hashchange", () => {
    const tab = tabFromHash();
    const current = Object.entries(views).find(([, el]) => !el.hidden)?.[0];
    if (tab !== current) setTab(tab, { pushHash: false });
  });

  /* Active section nav on scroll (visible tab only) */
  function activeLinks() {
    return [...document.querySelectorAll(".nav-links:not([hidden]) a")].filter(
      (a) => a.getAttribute("href")?.startsWith("#")
    );
  }

  const io = new IntersectionObserver(
    (entries) => {
      entries.forEach((e) => {
        if (!e.isIntersecting) return;
        const id = "#" + e.target.id;
        activeLinks().forEach((l) => l.classList.toggle("active", l.getAttribute("href") === id));
      });
    },
    { rootMargin: "-40% 0px -50% 0px", threshold: 0 }
  );

  [
    "positioning",
    "surfaces",
    "modules",
    "matrix",
    "stack",
    "out",
    "lanes",
    "roles-pick",
    "perm-matrix",
    "authz",
    "roles-notes",
    "orbit",
    "runsheet",
    "deferred",
  ].forEach((id) => {
    const el = document.getElementById(id);
    if (el) io.observe(el);
  });
})();
